INSERT INTO public.recipes (
  title, slug, description, image_url, source_url, category, cuisine,
  servings, prep_time_minutes, cook_time_minutes, difficulty, instructions,
  calories_per_serving, protein_g_per_serving, fat_g_per_serving, carbs_g_per_serving, fiber_g_per_serving, sodium_mg_per_serving,
  total_calories, total_protein_g, total_fat_g, total_carbs_g, total_fiber_g, total_sodium_mg, is_verified
) VALUES
  ('Đậu Hũ Nhồi Thịt Sốt Cà Chua', 'dau-hu-nhoi-thit-sot-ca-chua', 'Chào mọi người, lại là Bếp đây! 👋 Hôm nay Bếp muốn chia sẻ với các bạn một món ăn tuy quen mà lạ – đậu hũ nhồi thịt sốt cà chua. Quen vì đậu hũ với thịt xay thì nhà nào cũng hay có sẵn, mà lạ vì cách kết hợp này ăn hao [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2026/09/dauhudonthit.jpg', 'https://bepxua.vn/dau-hu-nhoi-thit-sot-ca-chua-%f0%9f%8d%85-mon-com-nha-ai-an-cung-ghien/', 'mon_man', 'vietnamese', 4, 15, 30, 'medium', '[{"step_number":1,"title":"Bước 1: Sơ Chế Đậu Hũ Và Làm Nhân Thịt","description":"Đậu hũ mua về cắt đôi, dùng muỗng nạo bỏ bớt phần ruột ở giữa để tạo khoảng trống nhồi nhân (nhớ nạo nhẹ tay kẻo bể đậu nha mọi người).\n\n\n\nThịt xay cho vào tô, thêm 1/2 phần hành tím, hành lá, ngò rí đã chuẩn bị, nêm 1 muỗng cà phê hạt nêm, 1 muỗng cà phê đường, 1 muỗng cà phê nước mắm, 1 ít tiêu xay rồi trộn đều tay cho thịt thấm gia vị."},{"step_number":2,"title":"Bước 2: Nhồi Thịt Vào Đậu Hũ","description":"Múc nhân thịt dồn vào từng miếng đậu hũ đã khoét ruột, dùng muỗng ém chặt tay để nhân không bị rớt ra khi chiên."},{"step_number":3,"title":"Bước 3: Chiên Đậu Hũ","description":"Bắc chảo lên bếp, làm nóng dầu rồi cho đậu hũ vào chiên với lửa vừa. Chiên đến khi mặt đậu vàng đều thì lật mặt còn lại, chiên tiếp cho vàng giòn cả hai mặt. Vớt đậu ra để riêng, để ráo bớt dầu.\n\n\n\n💡 Mẹo nhỏ từ Bếp: để lửa vừa thôi mọi người nhé, lửa lớn quá đậu dễ cháy vỏ mà nhân thịt bên trong chưa kịp chín đâu."},{"step_number":4,"title":"Bước 4: Nấu Sốt Cà Chua","description":"Cho 2 muỗng canh dầu ăn vào chảo, phi thơm phần gốc hành lá và hành tím còn lại. Sau đó cho cà chua vào xào khoảng 2 phút cho cà mềm nhũn ra.\n\n\n\nNêm vào 1 muỗng canh đường (gia giảm tùy độ chua của trái cà), 1 muỗng canh nước mắm, 1 muỗng canh nước tương, 1 muỗng canh tương ớt, 1 muỗng canh tương cà. Đảo đều tay khoảng 1-2 phút cho hỗn hợp sốt hòa quyện."},{"step_number":5,"title":"Bước 5: Om Đậu Hũ Với Sốt","description":"Đổ 150ml nước lọc vào chảo sốt, cho đậu hũ đã chiên vào. Lật đều các mặt đậu, om với lửa nhỏ khoảng 2-3 phút cho đậu thấm đều sốt cà chua sóng sánh."},{"step_number":6,"title":"Bước 6: Hoàn Thành","description":"Rắc thêm hành lá, ngò rí, tiêu xay lên trên cho dậy mùi thơm là xong! Múc ra dĩa, ăn nóng với cơm trắng thì khỏi phải bàn, đảm bảo nồi cơm hết sạch veo. 😋"}]'::jsonb, 310.8, 22.3, 16.6, 17.8, 1.5, 3180.9, 1243.4, 89.2, 66.4, 71.4, 5.9, 12723.5, true),
  ('Cá Nục Kho Nước Mía Đậm Đà, Ngọt Thanh', 'ca-nuc-kho-nuoc-mia-dam-da-ngot-thanh-an-com-hay-banh-mi-deu-cuon', 'Meta description: Cách làm cá nục kho nước mía đậm đà, thịt cá săn chắc, nước kho sánh keo ngọt thanh tự nhiên. Công thức chi tiết, dễ làm tại nhà, ăn với cơm hay bánh mì đều ngon. Từ khóa mục tiêu: cá nục kho nước mía, cách kho cá nục, cá nục kho, [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2026/09/ca-nuc-kho-rucs.jpg', 'https://bepxua.vn/ca-nuc-kho-nuoc-mia-dam-da-ngot-thanh-an-com-hay-banh-mi-deu-cuon/', 'mon_kho', 'vietnamese', 4, 20, 45, 'medium', '[{"step_number":1,"title":"Bước 1: Sơ chế cá","description":"Cá nục mua về Bếp làm sạch, đánh vảy, bỏ ruột, rửa lại cho hết nhớt và mùi tanh, để ráo."},{"step_number":2,"title":"Bước 2: Giã hành ớt","description":"Hành tím và ớt giã nát để khi ướp gia vị thấm đều và dậy mùi thơm hơn."},{"step_number":3,"title":"Bước 3: Ướp cá","description":"Cho tất cả gia vị gồm nước mắm, nước tương, nước màu thốt nốt, đường thốt nốt, muối, bột ngọt, mỡ heo và phần hành ớt giã vào tô cá. Trộn đều tay để cá thấm gia vị từ trong ra ngoài. Bọc kín tô, ướp cá khoảng 1-2 tiếng cho thấm."},{"step_number":4,"title":"Bước 4: Kho sơ cho cá săn","description":"Cho cá vào nồi, kho lửa vừa khoảng 2-3 phút đến khi thấy cá săn lại là được, chưa cần đổ nước vội."},{"step_number":5,"title":"Bước 5: Thêm nước mía, kho liu riu","description":"Đổ 300ml nước mía vào nồi, đậy nắp, để lửa nhỏ liu riu kho khoảng 45-60 phút. Đây là bước quan trọng nhất, mọi người nhớ để lửa nhỏ thôi để cá chín từ từ, thấm gia vị đều mà không bị nát."},{"step_number":6,"title":"Bước 6: Hoàn thiện","description":"Kho gần được 1 tiếng, nước kho sẽ sánh keo lại, bám đều quanh miếng cá. Bếp thường cho thêm vài lát ớt lên trên cho món ăn bắt mắt hơn trước khi tắt bếp."}]'::jsonb, 746.2, 53.4, 21.9, 83.6, 0.2, 2286.7, 2985, 213.5, 87.7, 334.5, 0.8, 9147, true),
  ('Mì Xào Bò Đậm Đà, Sợi Mì Dai, Thịt Bò Giòn Béo', 'cach-lam-mi-xao-bo-dam-da-soi-mi-dai-thit-bo-gion-beo', 'Hôm nay mình muốn chia sẻ với cả nhà một món ăn "cứu đói" cực kỳ hợp lý những hôm bận rộn mà vẫn muốn có bữa cơm tươm tất: mì xào bò. Chỉ với vài nguyên liệu quen thuộc trong bếp, chưa đến 20 phút là đã có ngay một dĩa mì xào nóng [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2026/09/mi-xao-bo.jpg', 'https://bepxua.vn/cach-lam-mi-xao-bo-dam-da-soi-mi-dai-thit-bo-gion-beo/', 'mon_an_sang', 'vietnamese', 4, 15, 20, 'medium', '[{"step_number":1,"title":"Bước 1 – Ướp thịt bò: ","description":"Thịt bò xắt lát mỏng, trộn đều với hạt nêm, dầu hào, dầu ăn và tiêu xay. Để khoảng 10-15 phút cho thấm."},{"step_number":2,"title":"Bước 2 – Pha sốt xào: ","description":"Trộn đều gói gia vị mì, nước tương, dầu hào, đường, tương cà và tương ớt trong một chén nhỏ, khuấy đều cho tan hết."},{"step_number":3,"title":"Bước 3 – Luộc mì: ","description":"Đun sôi nước, cho mì vào luộc khoảng 2 phút cho mì vừa mềm tới, vớt ra để ráo. Không luộc quá lâu kẻo mì bị nhũn, mất độ dai khi xào."},{"step_number":4,"title":"Bước 4 – Xào thịt bò: ","description":"Bắc chảo nóng, cho 1 muỗng canh mỡ vào, phi thơm 1/2 phần tỏi xay. Cho thịt bò vào xào lửa lớn khoảng 1 phút cho thịt vừa chín tới, giòn béo. Xào lửa lớn là bí quyết để thịt bò không bị dai và ra nước nhiều đó cả nhà. Xào xong gắp thịt ra dĩa để riêng."},{"step_number":5,"title":"Bước 5 – Xào cải: ","description":"Cùng chảo đó, cho thêm 2 muỗng canh mỡ, phi thơm phần tỏi xay còn lại. Cho cải ngọt vào đảo đến khi vừa xìu, thêm 1 muỗng canh sốt xào vào đảo đều cho cải thấm và chín tới."},{"step_number":6,"title":"Bước 6 – Trộn mì: ","description":"Cho mì đã luộc vào chảo, dùng đũa xốc nhẹ cho mì tơi ra, không bị vón cục. Rưới hết phần sốt xào còn lại vào, xốc đều tay cho mì thấm sốt và quyện với cải."},{"step_number":7,"title":"Bước 7 – Hoàn thiện: ","description":"Cho thịt bò và hành tây vào, xốc thêm khoảng 30 giây cho tất cả nguyên liệu hòa quyện rồi tắt bếp. Gắp ra dĩa, rắc thêm ngò rí và chút tiêu xay lên trên là xong."}]'::jsonb, 214.2, 17, 8.3, 18, 1.3, 1116.2, 856.7, 68.1, 33.1, 71.9, 5.2, 4464.9, true),
  ('Cơm Chiên Thập Cẩm Tơi Ngon Như Ngoài Tiệm', 'com-chien-thap-cam-toi-ngon-nhu-ngoai-tiem-cong-thuc-don-gian-ai-lam-cung-duoc', 'Nhà mình sáng nào cũng có nồi cơm nguội để dành, mà cứ để không thì phí lắm phải không mọi người? Vậy nên món cơm chiên thập cẩm luôn là "cứu tinh" của mình mỗi khi tủ lạnh có sẵn ít chả lụa, lạp xưởng, cà rốt, đậu que&#8230; Chỉ cần đảo vài phút [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2026/09/com-chien-thap-cam3.jpg', 'https://bepxua.vn/com-chien-thap-cam-toi-ngon-nhu-ngoai-tiem-cong-thuc-don-gian-ai-lam-cung-duoc/', 'mon_an_sang', 'vietnamese', 2, 15, 25, 'easy', '[{"step_number":1,"title":"Bước 1: Trộn cơm với trứng","description":"Cho cơm nguội vào tô, đập 3 lòng đỏ trứng vào, thêm hạt nêm, nước tương, bột ngọt. Trộn đều tay cho cơm thấm gia vị và áo đều lòng đỏ trứng."},{"step_number":2,"title":"Bước 2: Xào rau củ và thịt","description":"Bắc chảo, cho 1 muỗng canh mỡ heo phi thơm tỏi băm. Cho cà rốt, đậu que vào đảo khoảng 2 phút cho chín tới, tiếp tục cho chả lụa vào đảo thêm 30 giây, nêm 1 muỗng cafe hạt nêm rồi trút ra dĩa để riêng."},{"step_number":3,"title":"Bước 3: Chiên cơm","description":"Cho thêm 3 muỗng canh mỡ heo vào chảo, phi tỏi băm vàng thơm rồi cho phần cơm đã trộn trứng vào chiên. Đảo đều tay trên lửa lớn đến khi hạt cơm khô ráo, tơi và nảy tưng lên là đạt."},{"step_number":4,"title":"Bước 4: Hoàn thiện món ăn","description":"Cho lòng trắng trứng vào đảo khoảng 1 phút cho chín, sau đó trút phần rau củ thịt đã xào ở bước 2 vào, đảo thêm 1 phút cho hòa quyện. Cuối cùng cho hành lá vào, trộn đều rồi tắt bếp."}]'::jsonb, 1260.5, 35.1, 50.9, 165.3, 2.4, 2607.2, 2520.9, 70.1, 101.9, 330.7, 4.8, 5214.3, true),
  ('Gà Kho Sả Đậm Đà Thơm Lừng', 'ga-kho-sa-dam-da-thom-lung-mon-com-nha-ai-cung-ghien', 'Những ngày trời se lạnh hay mưa lâm thâm, chẳng gì bằng một nồi gà kho sả nóng hổi, đậm đà ăn cùng cơm trắng. Thịt gà thấm gia vị vừa ăn, nước kho sánh có màu vàng nâu đẹp mắt, thơm mùi sả với nước dừa tươi beo béo. Mình nấu món này hoài mà lần nào cả nhà cũng húp sạch nước kho luôn. Chị em cùng vào', 'https://bepxua.vn/wp-content/uploads/2026/09/ga-kho-sa.jpg', 'https://bepxua.vn/ga-kho-sa-dam-da-thom-lung-mon-com-nha-ai-cung-ghien/', 'mon_kho', 'vietnamese', 3, 20, 45, 'easy', '[{"step_number":1,"title":"Bước 1: Phi thơm gia vị","description":"Bắc chảo lên bếp, cho 2 muỗng canh dầu ăn vào đun nóng, sau đó cho hành tỏi ớt xay vào phi thơm cùng 1/2 phần sả đã chuẩn bị. Đảo đều tay đến khi dậy mùi thơm nức."},{"step_number":2,"title":"Bước 2: Xào săn thịt gà","description":"Cho thịt gà vào chảo, đảo đều cho thịt săn lại và thấm đều phần dầu hành tỏi ớt vừa phi."},{"step_number":3,"title":"Bước 3: Nêm gia vị và kho sơ","description":"Thêm vào 1 muỗng canh đường, 1 muỗng cà phê muối, 1 muỗng cà phê bột ngọt, 1 muỗng canh tương ớt và 1 muỗng cà phê nước màu dừa. Đảo đều rồi kho khoảng 3 phút cho gà thấm gia vị và lên màu đẹp."},{"step_number":4,"title":"Bước 4: Kho với nước dừa","description":"Đổ 300ml nước dừa tươi vào, kho tiếp 5-7 phút cho thịt gà mềm và nước kho sánh lại."},{"step_number":5,"title":"Bước 5: Hoàn thiện","description":"Cho 3 muỗng canh nước mắm cùng phần sả còn lại vào, đảo đều rồi kho thêm 2 phút cho dậy mùi. Cuối cùng thêm ớt tươi vào là xong."}]'::jsonb, 1480, 3.4, 10.3, 287.4, 5.3, 1297.3, 4440, 10.3, 31, 862.3, 15.9, 3891.9, true),
  ('chè đậu trắng dẻo thơm ngọt ngào', 'cach-nau-che-dau-trang-deo-thom-ngot-ngao', 'Chè đậu trắng, món ăn dân dã có nguồn gốc từ vùng Nam Bộ từ lâu đã trở thành thức quà quen thuộc trong lòng người Việt. Không chỉ đơn thuần là một món ăn giải nhiệt, chè đậu trắng còn là một phần ký ức tuổi thơ của bao người. Đây cũng là món [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2024/09/x_LzyFhT47U-HD.jpg', 'https://bepxua.vn/cach-nau-che-dau-trang-deo-thom-ngot-ngao/', 'mon_man', 'vietnamese', 4, 15, 30, 'medium', '[{"step_number":1,"title":"Bước 1","description":"Đậu trắng lựa bỏ hạt hư, ngâm nước qua đêm rồi rửa sạch, để ráo. Cho vào nồi 1,5l nước lọc và cho đậu vào nấu 40-45 phút cho đậu mềm."},{"step_number":2,"title":"Bước 2","description":"Nếp vo sạch, ngâm 30 phút. Dừa nạo vắt lấy 300ml nước cốt dừa nhất và 400ml nước cốt dừa dão."},{"step_number":3,"title":"Bước 3","description":"Đậu trắng luộc xong trút ra. Xếp lá dứa vào đáy 1 nồi khác rồi cho đậu đã luộc, nếp đã ngâm, đường vào nồi dàn đều, thêm 1 muỗng cafe muối rắc đều lên và cho nước cốt dừa dão, 900ml nước lọc vào nồi. Xong đậy nắp nấu chè với lửa vừa đến khi sôi thì hạ lửa nhỏ."},{"step_number":4,"title":"Bước 4","description":"Nấu chè khoảng 20 phút thì vớt lá dứa ra, đảo nhẹ. Cho 1 muỗng canh bột năng vào chén, thêm chút nước khuấy đều rồi cho vani vào khuấy sau đó rưới đều vào nồi chè, tiếp tục đảo nhẹ để chè có độ sệt. Nấu đến khi chè sệt lại thì tắt bếp."},{"step_number":5,"title":"Bước 5","description":"Làm nước cốt dừa ăn kèm: Cho vào chảo nước cốt dừa nhất, 1 muỗng canh đường, 1 muỗng canh bột năng, 1 ít muối rồi khuấy tan, nấu đến khi vừa sôi thì tắt bếp."},{"step_number":6,"title":"Bước 6","description":"Múc chè ra chén, chan nước cốt dừa lên và thưởng thức."}]'::jsonb, 791.5, 22.6, 2.3, 170.2, 3.6, 504, 3166.1, 90.4, 9.4, 680.9, 14.6, 2015.9, true),
  ('sườn non rim sả ớt mặn ngọt mềm mọng ngon lành', 'cach-lam-suon-non-rim-sa-ot-man-ngot-mem-mong-ngon-lanh', 'Sườn non heo, với phần thịt mềm, mỡ ít và xương sụn giòn tan là một trong những nguyên liệu được ưa chuộng trong ẩm thực Việt Nam và nhiều quốc gia khác. Bạn có thể chế biến sườn non heo thành rất nhiều món ăn hấp dẫn, từ truyền thống đến mới lạ theo [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2024/09/LK_MvTOpsTM-HD.jpg', 'https://bepxua.vn/cach-lam-suon-non-rim-sa-ot-man-ngot-mem-mong-ngon-lanh/', 'mon_kho', 'vietnamese', 4, 15, 30, 'medium', '[{"step_number":1,"title":"Bước 1","description":"Cho vào thau sườn non cùng 1 muỗng cafe muối và cho nước nóng vào trụng sơ thịt khoảng 2-3 phút cho sạch mùi tanh rồi vớt thịt ra rửa sạch, để ráo nước."},{"step_number":2,"title":"Bước 2","description":"Sả bào cho vào cối giã sơ cho sả mềm, ăn không bị xảm rồi trút sả ra. Cho tiếp tỏi, ớt, hành tím vào giã nát rồi cho 1 muỗng canh nước lọc vào trộn đều."},{"step_number":3,"title":"Bước 3","description":"Cho vào tô thịt, 1 muỗng cafe muối, nước hành tỏi ớt giã rồi trộn đều. Cho tiếp 2 muỗng canh bột bắp vào trộn đều với sườn để giúp sườn mềm, không bị khô khi chiên."},{"step_number":4,"title":"Bước 4","description":"Cho dầu ăn vào chảo đun nóng, dầu nóng cho sườn vào chiên lửa vừa đến khi vàng đều rồi vớt ra dĩa."},{"step_number":5,"title":"Bước 5","description":"Cho vào chén 1 muỗng canh đường, 1,5 muỗng canh nước mắm, 2 muỗng canh tương ớt, 100ml nước nóng vào khuấy đều làm sốt rim sườn."},{"step_number":6,"title":"Bước 6","description":"Cho 3 muỗng canh dầu ăn vào chảo đã rửa sạch đun nóng, dầu nóng cho xác hành tỏi ớt vào phi thơm rồi cho sả vào phi vừa vàng và vớt ra."},{"step_number":7,"title":"Bước 7","description":"Cho sườn chiên và nước sốt vào chảo đảo đều với lửa nhỏ cho sốt ngấm vào sườn, đến khi sốt sệt lại thì cho sả phi vào đảo đều cho sả bám đều sườn thì tắt bếp."},{"step_number":8,"title":"Bước 8","description":"Cho sườn non rim sả ớt ra dĩa, ăn với cơm nóng và thưởng thức."}]'::jsonb, 522.5, 46.1, 32.1, 12.3, 0.4, 1125, 2090.2, 184.3, 128.3, 49, 1.6, 4499.8, true),
  ('sườn non chay rim nước mía xá xíu mặn ngọt ăn là ghiền', 'cach-lam-suon-non-chay-rim-nuoc-mia-xa-xiu-man-ngot-an-la-ghien', 'Nếu như sườn non là một nguyên liệu rất được ưa thích trong ẩm thực mặn thì sườn non chay cũng rất được “bồ kết” trong ẩm thực chay. Được làm từ đậu nành, lúa mì hoặc các loại thực phẩm giàu protein thực vật khác; sườn non chay không chỉ đáp ứng nhu cầu [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2024/08/youthumb_eX921P2SQhI_maxres.jpg', 'https://bepxua.vn/cach-lam-suon-non-chay-rim-nuoc-mia-xa-xiu-man-ngot-an-la-ghien/', 'mon_chay', 'vietnamese', 4, 15, 30, 'easy', '[{"step_number":1,"title":"Bước 1","description":"Sườn non chay ngâm nước khoảng 3-4h cho mềm rồi vắt sả 2-3 lần nước sau đó khứa caro."},{"step_number":2,"title":"Bước 2","description":"Cho sườn non chay vào chảo dầu nóng chiên đến khi vàng đều sau đó tăng lửa lớn chiên thêm 2 phút rồi gắp ra."},{"step_number":3,"title":"Bước 3","description":"Tỏi cho vào máy xay gia vị xay nhuyễn. Cho tỏi vào chảo vừa chiên, đã chắt dầu để lại một ít phi thơm rồi cho nước mía vào, thêm 3 muỗng canh sốt ướp xá xíu, 1 muỗng canh nước tương, 1 muỗng cafe hạt nêm chay, 2 muỗng cafe đường nấu sôi."},{"step_number":4,"title":"Bước 4","description":"Cho sườn non chiên vào chảo sốt vừa sôi lật cho sốt thấm đều sườn, chú ý hạ lửa nhỏ. Lật đến khi sườn thấm sốt rồi thì rắc mè rang lên và tắt bếp."},{"step_number":5,"title":"Bước 5","description":"Cho sườn non chay rim nước mía xá xíu ra dĩa,  ăn cùng cơm nóng, bún, bánh hỏi… và thưởng thức."}]'::jsonb, 268.5, 5.3, 3.2, 54.6, 0.2, 712.2, 1074, 21.1, 13, 218.3, 0.6, 2849, true),
  ('sườn non kho tiêu mềm ngon mặn ngọt hao cơm', 'cach-lam-suon-non-kho-tieu-mem-ngon-man-ngot-hao-com', 'Nếu đang “đau đầu” chọn lựa món cho các bữa ăn hàng ngày của gia đình, bạn đừng quên cân nhắc đến các món từ sườn non heo nhé. Đây là phần thịt heo rất được yêu thích vì nhiều thịt ít xương, ít mỡ, sụn mềm giòn; dễ chế biến thành nhiều món ăn [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2024/07/maxresdefault-3.jpg', 'https://bepxua.vn/cach-lam-suon-non-kho-tieu-mem-ngon-man-ngot-hao-com/', 'mon_kho', 'vietnamese', 4, 20, 45, 'easy', '[{"step_number":1,"title":"Bước 1","description":"Tỏi, hành tím cho vào máy xay gia vị xay nhuyễn. Sườn non rửa sạch, cho vào tô sườn non,  ½ phần hành tỏi xay, 1 muỗng cafe muối, 1 muỗng cafe hạt nêm, 3 muỗng canh đường, 2 muỗng canh nước mắm,1 muỗng cafe bột ngọt, tiêu xay trộn đều, ướp 15 phút."},{"step_number":2,"title":"Bước 2","description":"Cho 1 muỗng canh nước màu (gia giảm tùy theo độ đậm nhạt màu) vào tô thịt trộn đều. Cho 2 muỗng canh dầu ăn vào chảo và đun nóng, dầu nóng cho phần hành tỏi xay còn lại vào phi thơm rồi cho sườn non vào đảo đều, kho lửa vừa từ 7-10 phút."},{"step_number":3,"title":"Bước 3","description":"Cho 500ml nước nóng vào chảo thịt rồi đậy nắp kho khoảng 25-30 phút, thỉnh thoảng mở nắp đảo đều trong lúc kho. Kho thịt đến khi cạn nước vừa ý thì tắt bếp."},{"step_number":4,"title":"Bước 4","description":"Cho sườn non kho tiêu ra dĩa, thêm hành lá, ớt, tiêu xay tùy ý. Ăn cùng cơm nóng và thưởng thức."}]'::jsonb, 538.9, 45.7, 32.1, 16.8, 0.3, 1605.5, 2155.4, 182.8, 128.3, 67, 1.1, 6421.9, true),
  ('cá bống chay chiên sả giòn giòn cực ngon', 'cach-lam-ca-bong-chay-chien-sa-gion-gion-cuc-ngon', 'Với việc mô phỏng theo những món ăn mặn, ẩm thực chay ngày càng trở nên đa dạng và hấp dẫn hơn với những món ăn thỏa mãn cả hương vị lẫn hình thức. Đều là những nguyên liệu thiên nhiên nhưng qua sự khéo tay và sáng tạo của các đầu bếp, những món [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2024/06/maxresdefault-2-1.jpg', 'https://bepxua.vn/cach-lam-ca-bong-chay-chien-sa-gion-gion-cuc-ngon/', 'mon_chay', 'vietnamese', 4, 15, 25, 'medium', '[{"step_number":1,"title":"Bước 1","description":"Cá bống chay đem ngâm nước cho mềm trong 10 phút rồi rửa lại 2-3 lần nước, vắt thật khô. Cho cá bống chay vào tô, nêm ½ muỗng cafe muối xốc đều."},{"step_number":2,"title":"Bước 2","description":"Cho sả bào vào máy xay xay nhuyễn vừa. Cho 1 chén dầu ăn vào chảo và đun nóng, dầu nóng cho sả xay vào phi thơm đến khi sả vàng thì trút ra rây lấy riêng sả phi."},{"step_number":3,"title":"Bước 3","description":"Cho lại dầu phi sả vào chảo cho xăm xắp, đun nóng dầu rồi cho cá bống chay vào chiên lửa vừa đến khi vàng đều thì vớt cá bống chay ra dĩa có lót giấy thấm dầu."},{"step_number":4,"title":"Bước 4","description":"Trút dầu trong chảo, cho lại vào chảo 1 muỗng cafe hạt nêm chay, ½ muỗng canh đường, 2 muỗng canh nước tương, 2 muỗng canh nước lọc, 1 muỗng cafe ớt rim rồi đảo đều nấu sôi."},{"step_number":5,"title":"Bước 5","description":"Cho cá bống chay chiên vào chảo sốt, xốc đều cá bống chay chiên cho thấm sốt với lửa nhỏ sau đó cho sả phi vào trộn đều và tắt bếp."},{"step_number":6,"title":"Bước 6","description":"Cho cá bống chay chiên sả ra dĩa, ăn cùng cơm nóng và thưởng thức."}]'::jsonb, 58.3, 4.8, 0.2, 9.4, 0.3, 3818.1, 233.2, 19, 0.8, 37.5, 1.2, 15272.5, true),
  ('sườn chay rim mặn ngọt ngon lạ miệng', 'cach-lam-suon-chay-rim-man-ngot-ngon-la-mieng', 'Giống như sườn non được ưa chuộng trong các món mặn, đối với các tín đồ ăn chay, sườn non chay cũng là một nguyên liệu thường xuyên được lựa chọn trong việc chuẩn bị món ăn. Được làm hoàn toàn từ các thành phần thiên nhiên như đậu nành, lúa mì, gia vị chay, [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2024/06/maxresdefault-2.jpg', 'https://bepxua.vn/cach-lam-suon-chay-rim-man-ngot-ngon-la-mieng/', 'mon_chay', 'vietnamese', 4, 15, 30, 'medium', '[{"step_number":1,"title":"Bước 1","description":"Sườn non chay đem ngâm nước khoảng 4-5h cho nở mềm. Sau khi ngâm đem sườn non chay vắt rửa 2-3 lần nước sau đó vắt thật khô. Cắt sườn non chay thành 4 phần."},{"step_number":2,"title":"Bước 2","description":"Khoai lang gọt vỏ, rửa sạch, xắt miếng dài. Dùng đũa xắn miếng sườn chay ra rồi nhét khoai vào sườn. Cho vào tô sườn nhồi khoai 2 muỗng canh bột chiên giòn xóc đều."},{"step_number":3,"title":"Bước 3","description":"Bắc chảo lên bếp, cho dầu ăn vào xăm xắp nấu sôi dầu sau đó hạ lửa nhỏ vừa và cho sườn chay nhồi khoai vào chiên vàng đều. Sườn vàng rồi thì gắp ra dĩa lót giấy thấm dầu."},{"step_number":4,"title":"Bước 4","description":"Chắt hết dầu trong chảo, chỉ chừa lại một ít. Cho 1 muỗng canh đường, 6 muỗng canh nước tương, 1 muỗng canh tương ớt, 1 muỗng canh dầu hào chay, ⅓ muỗng cafe ngũ vị hương, ½ muỗng cafe tỏi bột, tiêu xay, 5 muỗng canh nước lọc vào chảo nấu sôi."},{"step_number":5,"title":"Bước 5","description":"Cho lại sườn chiên vào chảo sốt, đảo cho sốt bám đều sườn rồi tắt bếp."},{"step_number":6,"title":"Bước 6","description":"Cho sườn chay rim mặn ngọt ra dĩa, ăn với cơm nóng và thưởng thức."}]'::jsonb, 126.1, 7.1, 3.3, 17, 0.7, 1506.1, 504.6, 28.5, 13.2, 68, 2.8, 6024.4, true),
  ('tôm rim mặn ngọt và salad trộn dầu giấm ngon khó cưỡng', 'cach-lam-tom-rim-man-ngot-va-salad-tron-dau-giam-ngon-kho-cuong', 'Con tôm với vị ngọt tự nhiên, thịt chắc và giàu dinh dưỡng, từ lâu đã trở thành một trong những nguyên liệu hải sản được yêu thích hàng đầu trong ẩm thực trên khắp thế giới. Từ những món ăn dân dã hàng ngày đến những món ăn cao cấp, tôm đều xuất hiện [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2024/09/youthumb_b3kotHG8Hgg_maxres.jpg', 'https://bepxua.vn/cach-lam-tom-rim-man-ngot-va-salad-tron-dau-giam-ngon-kho-cuong/', 'mon_kho', 'vietnamese', 4, 15, 30, 'medium', '[{"step_number":1,"title":"Bước 1","description":"Tôm lột vỏ, bỏ chỉ lưng, rửa qua nước muối rồi rửa sạch lại, để ráo. Cho tỏi vào máy xay gia vị xay nhuyễn. Rau củ rửa sạch, thái sợi nhỏ củ."},{"step_number":2,"title":"Bước 2","description":"Cho 100ml dầu ăn vào chảo đun nóng, dầu nóng cho tỏi xay vào phi vừa vàng thì trút ra chén, để lại một ít tỏi phi trong chảo."},{"step_number":3,"title":"Bước 3","description":"Cho 4 muỗng canh giấm ăn, 1,5 muỗng canh đường, ½ muỗng cafe muối, tiêu xay, 1 muỗng canh dầu ăn vào chảo rồi khuấy đều nấu sôi 1 phút làm sốt dầu giấm."},{"step_number":4,"title":"Bước 4","description":"Cho vào chén 3 muỗng canh nước lọc, 2 muỗng canh nước mắm, 1 muỗng canh dầu hào, 1 muỗng canh tương ớt, 1,5 muỗng canh đường, tiêu xay khuấy tan."},{"step_number":5,"title":"Bước 5","description":"Cho vào thố rau xà lách, ớt chuông, cà rốt, dưa leo, hành tây tím rồi cho sốt dầu giấm đã để nguội vào trộn đều nhẹ tay đến khi vừa ý."},{"step_number":6,"title":"Bước 6","description":"Cho 3 muỗng canh dầu tỏi phi vào chảo đun nóng, dầu nóng cho tôm vào đảo đều rồi cho chén nước sốt vào rim lửa nhỏ 5-7 phút, lật đều tôm cho thấm sốt. Rim đến khi sốt sệt lại thì rải tỏi phi lên tôm, thêm ngò trang trí tùy ý và tắt bếp."},{"step_number":7,"title":"Bước 7","description":"Cho tôm ra dĩa, ăn cùng cơm nóng và salad sốt dầu giấm và thưởng thức."}]'::jsonb, 180.4, 24.6, 2.4, 15.2, 0.4, 3644.1, 721.7, 98.3, 9.4, 60.8, 1.7, 14576.6, true),
  ('thịt ba chỉ kho tiêu nước sệt ngon vô đối', 'cach-lam-thit-ba-chi-kho-tieu-nuoc-set-ngon-vo-doi', 'Thịt ba chỉ kho tiêu là món ăn rất đỗi quen thuộc trong những bữa ăn hàng ngày của chúng ta. Món ăn này có cách làm đơn giản, dễ ăn không ngán, hợp cho từ người lớn đến trẻ nhỏ. Bạn có thể kho một nồi thịt và để dành ăn cơm dần trong [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2024/04/maxresdefault.jpg', 'https://bepxua.vn/cach-lam-thit-ba-chi-kho-tieu-nuoc-set-ngon-vo-doi/', 'mon_kho', 'vietnamese', 4, 20, 45, 'easy', '[{"step_number":1,"title":"Bước 1","description":"Thịt rửa sạch, xắt miếng vừa ăn. Cho vào tô thịt 1 muỗng cafe đường, 1 muỗng cafe hạt nêm, tiêu xay trộn đều ướp 15 phút. Cho tỏi, hành tím vào máy xay gia vị xay nhuyễn."},{"step_number":2,"title":"Bước 2","description":"Cho dầu ăn vào chảo đun nóng, dầu nóng cho thịt đã ướp vào áp chảo cho thịt săn lại rồi tắt bếp."},{"step_number":3,"title":"Bước 3","description":"Bắc nồi lên bếp, cho vào nồi 1 muỗng canh đường, 1 muỗng canh dầu ăn rồi bật lửa đảo đều làm màu kho thịt sau đó cho hành tỏi xay vào phi thơm rồi cho tiếp 200ml nước lọc vào nồi. Nêm 2 muỗng canh nước mắm, 2 muỗng canh tương ớt đảo đều."},{"step_number":4,"title":"Bước 4","description":"Cho thịt áp chảo vào nồi, đậy nắp kho lửa nhỏ 15-20 phút. Thỉnh thoảng mở nắp đảo đều thịt trong lúc kho, kho đến khi nước sệt vừa ý thì tắt bếp, thêm tiêu xay tùy thích."},{"step_number":5,"title":"Bước 5","description":"Cho thịt ba chỉ kho tiêu ra dĩa, ăn cùng cơm nóng và thưởng thức."}]'::jsonb, 225.7, 13.2, 16.2, 6.7, 0.3, 528.7, 902.9, 52.7, 64.9, 26.8, 1.2, 2114.8, true),
  ('cánh gà om bia thơm ngon hấp dẫn', 'cach-lam-canh-ga-om-bia-thom-ngon-hap-dan', 'Bia không những là thức uống ưa thích của “cánh mày râu” mà còn là một nguyên liệu hay ho được dùng trong nhà bếp. Trong ẩm thực, so với rượu thì bia được đánh giá là có nồng độ cồn ít hơn, mùi vị nhẹ hơn, là yếu tố nâng tầm cho nhiều món [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2024/03/maxresdefault-8.jpg', 'https://bepxua.vn/cach-lam-canh-ga-om-bia-thom-ngon-hap-dan/', 'mon_man', 'vietnamese', 4, 15, 30, 'easy', '[{"step_number":1,"title":"Bước 1","description":"Cánh gà bóp muối rửa sạch, khứa đều. Hành tím, tỏi, gừng cho vào máy xay gia vị xay nhuyễn."},{"step_number":2,"title":"Bước 2","description":"Cho vào thố gà ½ muỗng canh hạt nêm, ½ muỗng cafe muối, 2 muỗng canh nước mắm, gừng tỏi hành tím đã xay, 2 muỗng canh tương ớt rồi trộn đều, ướp 15-30 phút."},{"step_number":3,"title":"Bước 3","description":"Cho 5 muỗng canh dầu ăn vào chảo đun nóng, dầu nóng cho 1 muỗng canh đường vào thắng màu rồi cho cánh gà vào chiên cháy cạnh đều 2 mặt."},{"step_number":4,"title":"Bước 4","description":"Cho bia vào chảo gà, nấu lửa vừa đến khi cạn thì tắt bếp."},{"step_number":5,"title":"Bước 5","description":"Cho cánh gà om bia ra dĩa, ăn cùng cơm nóng và thưởng thức."}]'::jsonb, 484.5, 33.8, 34.1, 6.5, 0.2, 3093.8, 1937.9, 135.2, 136.3, 25.9, 0.8, 12375.1, true),
  ('tôm khô xẻ dẻo thơm và công thức mắm me mê ly ăn tôm nướng', 'cach-lam-tom-kho-xe-deo-thom-va-cong-thuc-mam-me-me-ly-an-tom-nuong', 'Tôm khô xẻ hay tôm lụi là một đặc sản của Cà Mau. Sở dĩ có tên gọi độc đáo này vì dựa trên hình dạng của tôm khô sau khi làm, phần thân tôm được bóc vỏ và cán dẹp ra, phần đuôi tôm thì giữ lại vỏ sau đó đem đi phơi nắng.Tôm [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2024/02/maxresdefault-4-1.jpg', 'https://bepxua.vn/cach-lam-tom-kho-xe-deo-thom-va-cong-thuc-mam-me-me-ly-an-tom-nuong/', 'mon_man', 'vietnamese', 4, 15, 30, 'easy', '[{"step_number":1,"title":"Bước 1","description":"Cho 1 muỗng canh muối vào thau đá rồi đổ nước vào sau đó cho tôm vào thau ngâm cho dễ lột. Tôm lột bỏ đầu, lột vỏ, xẻ tôm bỏ chỉ lưng, vừa làm vừa giữ trong thau đá lạnh cho tôm tươi."},{"step_number":2,"title":"Bước 2","description":"Trút tôm ra rổ, lau tôm cho ráo nước rồi cho ra tô. Cho vào tô tôm sa tế tôm, 1 muỗng cafe tiêu xay trộn đều."},{"step_number":3,"title":"Bước 3","description":"Xếp tôm đã ướp ra mẹt, dàn đều tôm rồi phơi nắng 1-2 ngày tùy thích đến khi tôm đạt độ dẻo khô vừa ý.Tôm phơi xong là có thể ăn liền, khi ăn bạn lấy phần tôm đủ  dùng, phần còn lại bảo quản ngăn mát."},{"step_number":4,"title":"Bước 4","description":"Cách làm tôm nướng chấm mắm me: Tôm cho vào nồi chiên không dầu nướng sơ. Cho vào chảo me chín và 1 chén nước lọc rồi dầm ra nước me sau đó rây lấy cốt me, bỏ xác me; cho vào chảo cốt me 6 muỗng canh đường, 6 muỗng canh nước mắm, 1 muỗng canh tương ớt, ½ muỗng canh bột ngọt khuấy đều nấu sôi 2-3 phút rồi tắt bếp. Múc mắm me ra chén, thêm ớt tùy thích nếu muốn ăn cay."},{"step_number":5,"title":"Bước 5","description":"Cho tôm nướng ra dĩa, chấm mắm me và thưởng thức."}]'::jsonb, 552.2, 94.1, 5.1, 32.7, 0.9, 5196.9, 2208.9, 376.3, 20.4, 130.6, 3.6, 20787.8, true)
